-- Lokal demo: uygulama senaryodaki 'bugün'ü görsün. Gerçek tarihe dönmek için bu satırı silin.
create or replace function yerel_bugun(saat_dilimi text) returns date language sql stable as $$
  select coalesce(nullif(current_setting('app.bugun', true), '')::date, date '2026-10-25')
$$;
